// Each distractor has its own explanation. The helper only normalises presentation.
type Check = [string, string, string, string, string, string, string];
export function question(id: string, c: Check, rotation = 0): Question {
  const options = [{ text: c[1], feedback: c[2] }, { text: c[3], feedback: c[4] }, { text: c[5], feedback: c[6] }];
  return { id, prompt: c[0], options: [...options.slice(rotation), ...options.slice(0, rotation)], correct: (3 - rotation) % 3, explanation: c[2] };
}
type Seed = {
  n: string; title: string; objective: string; situation: string; concept: string;
  terms: [string, string][]; example: string[]; practice: Check; checks: [Check, Check, Check]; takeaways: string[];
  refs?: SourceReference[];
};
